INSERT INTO HistoricPriceEMA ( isin, [Date], [Close], SMA5, SMA20, SMA50, SMA100, SMA200 )
SELECT o.isin, o.Date, o.Close, (SELECT avg(Close)        FROM HistoricPrice i        WHERE i.isin=o.isin and i.indice <= o.indice            AND i.indice >= (o.indice - 4)        having count(*) >=5        ) AS SMA5, (SELECT avg(Close)        FROM HistoricPrice i        WHERE  i.isin=o.isin and i.indice <= o.indice            AND i.indice >= (o.indice - 19)        having count(*) >=20        ) AS SMA20, (SELECT avg(Close)        FROM HistoricPrice i        WHERE  i.isin=o.isin and i.indice <= o.indice            AND i.indice >= (o.indice - 49)        having count(*) >=50        ) AS SMA50, (SELECT avg(Close)        FROM HistoricPrice i        WHERE  i.isin=o.isin and i.indice <= o.indice            AND i.indice >= (o.indice - 99)        having count(*) >=100         ) AS SMA100, (SELECT avg(Close)        FROM HistoricPrice i        WHERE  i.isin=o.isin and i.indice <= o.indice            AND i.indice >= (o.indice - 199)        having count(*) >=200        ) AS SMA200
FROM HistoricPrice AS o INNER JOIN 1ISIN ON o.ISIN = [1ISIN].ISIN
WHERE (((o.Date)>Now()-50))
ORDER BY o.isin, o.Date;
